  "media-route": { file: "backend/src/modules/core/media/media.controller.ts", lines: "49\u201365", lang: "ts", code: "@RouteClass('upload')\n@Post('upload/profile-photo')\n@UseGuards(JwtGuard)\n@UseInterceptors(\n    FileInterceptor('file', {\n        storage: memoryStorage(),\n        // Grenze schon beim Einlesen: sonst liegt eine beliebig grosse Datei komplett im RAM,\n        // bevor der Service sie ablehnt (413 statt voller Heap).\n        limits: { fileSize: MAX_SIZE_BYTES, files: 1 },\n        fileFilter: (_req, file, cb) => {\n            if (ALLOWED_MIME_TYPES.includes(file.mimetype)) {\n                cb(null, true);\n            } else {\n                cb(new BadRequestException('Nur JPEG, PNG und WebP erlaubt'), false);\n            }\n        },\n    })," },
  "media-raw": { file: "backend/src/modules/core/media/media.service.ts", lines: "61\u201380", lang: "ts", code: "// Uploads the raw file immediately under its final key so the response\n// stays fast — resize/watermark happens in MediaProcessor (worker\n// process), which overwrites this same object a few seconds later. No\n// schema change: file_url is populated from the start, it just briefly\n// points at the unprocessed image.\nasync uploadProfilePhoto(\n    userId: string,\n    file: Express.Multer.File,\n): Promise<{ file_url: string; id: string }> {\n    if (file.size > MAX_SIZE_BYTES) {\n        throw new BadRequestException('Datei zu groß. Maximal 5 MB erlaubt.');\n    }\n\n    if (!this.validateMagicBytes(file.buffer)) {\n        throw new BadRequestException('Ungültiges Dateiformat');\n    }\n\n    const filename = `${userId}-${Date.now()}.webp`;\n    const storageKey = `profiles/${filename}`;\n    const fileUrl = await uploadObject(storageKey, file.buffer, file.mimetype);" },
