  "media-retry": { file: "backend/src/common/queue/queue.constants.ts", lines: "6\u201315", lang: "ts", code: "// Shared across all queues registered via BullModule.registerQueue(..., { defaultJobOptions }).\n// 3 retries with exponential backoff so a transient failure (S3 hiccup, DB\n// blip) self-heals without manual intervention; removeOnComplete/Fail caps\n// keep Redis from growing unbounded with job history.\nexport const DEFAULT_JOB_OPTIONS = {\n    attempts: 3,\n    backoff: { type: 'exponential' as const, delay: 1000 },\n    removeOnComplete: { count: 100 },\n    removeOnFail: { count: 500 },\n};" },
  "media-worker": { file: "backend/src/worker.ts", lines: "7\u201312", lang: "ts", code: "async function bootstrap() {\n    const app = await NestFactory.createApplicationContext(WorkerModule);\n    app.enableShutdownHooks();\n    new Logger('Worker').log('Worker gestartet — verbunden mit DB und Redis, wartet auf Jobs.');\n    new Logger('Tenant').log(describeTenantInfra());\n}" },
  "media-sharp": { file: "backend/src/modules/core/media/media.processor.ts", lines: "61\u201366, 84\u201385", lang: "ts", code: "const rawBuf = await downloadObject(storageKey);\n\nconst resizedBuf = await sharp(rawBuf)\n    .resize(800, 800, { fit: 'inside', withoutEnlargement: true })\n    .webp({ quality: 80 })\n    .toBuffer();\n…\n// Same key as the raw upload — overwrites it, file_url stays stable.\nawait uploadObject(storageKey, finalBuf, 'image/webp');" },
  "prot-flag": { file: "backend/src/modules/core/care/care.service.ts", lines: "195\u2013198", lang: "ts", code: "async setProtection(caretakerId: string, clientId: string, on: boolean) {\n    await this.requireRight(caretakerId, clientId, 'can_set_protection');\n    await this.dataSource.query('UPDATE users SET enhanced_protection = $2 WHERE id = $1', [clientId, on]);\n    return { ok: true };" },
  "prot-audit": { file: "backend/migrations/001_baseline.sql", lines: "782\u2013800", lang: "sql", code: "CREATE FUNCTION public.trigger_log_vulnerable_flag() RETURNS trigger\n    LANGUAGE plpgsql\n    AS $$\n\nBEGIN\n\n  IF OLD.vulnerable_flag IS DISTINCT FROM NEW.vulnerable_flag THEN\n\n    INSERT INTO vulnerable_flag_audit (\n\n      user_id, old_value, new_value, changed_at\n\n    ) VALUES (\n\n      NEW.id, OLD.vulnerable_flag, NEW.vulnerable_flag, NOW()\n\n    );\n\n  END IF;" },
  "prot-search": { file: "backend/src/modules/core/profile/profile.service.ts", lines: "522\u2013526", lang: "ts", code: ".where('p.is_published = true')\n.andWhere('u.is_banned = false')\n.andWhere('u.deleted_at IS NULL')\n.andWhere('u.enhanced_protection = false')\n.andWhere('u.vulnerable_flag = false')" },
  "prot-contact": { file: "backend/src/modules/core/chat/chat.service.ts", lines: "129\u2013141", lang: "ts", code: "// Betreuung (Modul caretaker): Bei vulnerable_flag und aktiver\n// Betreuung mit can_set_protection zaehlt das Ja erst, wenn die\n// Betreuung freigibt (CareService.decide). Rohes SQL, weil die\n// Spalten aus 006 nur in Mandanten mit dem Modul gebraucht werden.\nif (isModuleEnabled('caretaker')) {\n    const held = await this.contactRequestRepository.manager.query(\n        `UPDATE contact_requests cr SET receiver_accepted_at = now(), caretaker_status = 'pending'\n          WHERE cr.id = $1 AND cr.caretaker_status IS NULL AND EXISTS (\n                SELECT 1 FROM managed_accounts ma JOIN users u ON u.id = ma.user_id\n                 WHERE ma.user_id = cr.receiver_id AND u.vulnerable_flag AND ma.can_set_protection\n                   AND ma.accepted_at IS NOT NULL AND ma.revoked_at IS NULL\n                   AND (ma.expires_at IS NULL OR ma.expires_at > now()))\n         RETURNING cr.id`," },
  "prot-board": { file: "backend/src/modules/core/board/board.service.ts", lines: "126\u2013129", lang: "ts", code: "if (dto.visibility === 'public') {\n    // Schutz-Markierung: nur im Umkreis, nie oeffentlich (Datenschutz 4.3)\n    if (user.vulnerable_flag) {\n        throw new ForbiddenException('Mit Schutz-Markierung sind nur Aushänge im Umkreis möglich');" },
  "prot-rls": { file: "backend/migrations/001_baseline.sql", lines: "1383, 3292", lang: "sql", code: "ALTER TABLE ONLY public.profile_sensitive_data FORCE ROW LEVEL SECURITY;\n…\nCREATE POLICY own_data ON public.profile_sensitive_data USING ((user_id = (NULLIF(current_setting('app.current_user_id'::text, true), ''::text))::uuid)) WITH CHECK ((user_id = (NULLIF(current_setting('app.current_user_id'::text, true), ''::text))::uuid));" },
  "prot-withrls": { file: "backend/src/common/database/rls.helper.ts", lines: "28\u201335", lang: "ts", code: "const qr = dataSource.createQueryRunner();\nawait qr.connect();\nawait qr.startTransaction();\ntry {\n  // SET LOCAL is visible only within this transaction and on this connection.\n  await qr.query('SET LOCAL app.current_user_id = $1', [userId]);\n  const result = await fn(qr.manager);\n  await qr.commitTransaction();" },
  "load-stack": { file: "docker-compose.loadtest.yml", lines: "1\u201312", lang: "yaml", code: "# Loadtest-Stack als Override, NICHT als Ersatz fuer docker-compose.yml.\n# docker-compose.yml (Demo) bleibt unveraendert — diese Datei wird zusaetzlich\n# geladen und fuegt neue Services hinzu, ueberschreibt keinen Demo-Service.\n#\n# Start (Demo- und Loadtest-Stack zusammen, im selben Compose-Projekt):\n#   docker compose -f docker-compose.yml -f docker-compose.loadtest.yml up -d \\\n#     XXX_db_load XXX_redis_load minio-load minio-load-init XXX_worker_load XXX_backend_load pgadmin\n#\n# Eigenes DB-Volume (XXX_load_pgdata), eigenes Redis (XXX_redis_load), eigenes\n# MinIO (minio-load), ein eigener Worker (XXX_worker_load) und ein eigenes\n# Netzwerk (XXX_load_network) — die Demo-DB/-Redis/-MinIO/-Worker/das\n# Demo-Volume/-Netzwerk werden nie beruehrt." },
  "load-lb": { file: "backend/scripts/loadtest/nginx-lb.conf", lines: "15\u201323, 25\u201331", lang: "nginx", code: "upstream backend_fast {\n    zone backend_fast 64k;\n    least_conn;\n    server XXX_backend_load:3000 resolve max_fails=0;\n    server XXX_backend_load_replica:3000 resolve max_fails=0;\n    keepalive 128;\n    # Kuerzer als Nodes keepAliveTimeout (65 s, main.ts), damit nginx nie eine Verbindung nimmt, die Node gerade schliesst.\n    keepalive_timeout 4s;\n}\n…\nupstream backend_heavy {\n    zone backend_heavy 64k;\n    least_conn;\n    server XXX_backend_load_heavy:3000 resolve max_fails=0;\n    keepalive 32;\n    keepalive_timeout 4s;\n}" },
  "load-key": { file: "backend/src/common/loadtest/loadtest-key.ts", lines: "21\u201328", lang: "ts", code: "export function isLoadtestRequest(req: { headers?: Record<string, string | string[] | undefined> } | undefined): boolean {\n    if (!loadtestEnabled()) return false;\n    const sent = req?.headers?.[LOADTEST_HEADER];\n    if (typeof sent !== 'string') return false;\n    const a = Buffer.from(sent);\n    const b = Buffer.from(process.env.LOADTEST_KEY as string);\n    return a.length === b.length && timingSafeEqual(a, b);\n}" },
